def hand(a,x,y,near,kind,who):
    mid,light=(4,5) if near else (3,4)
    if who=='jack':
        a.shape([(x+1,y-2),(x+10,y-2),(x+15,y+2),(x+16,y+9),(x+13,y+15),(x+7,y+18),(x,y+15),(x-3,y+10),(x-3,y+4)],11 if near else 10)
        a.patch([(x+2,y),(x+9,y),(x+13,y+3),(x+12,y+7),(x,y+7),(x-1,y+4)],12 if near else 11)
        a.line([(x,y+12),(x+5,y+15),(x+11,y+12)],10 if near else 1)
        a.line([(x,y+16),(x+7,y+18)],19,2)
        a.box(x-3,y-2,20,21)
    elif kind=='ground':
        a.shape([(x,y+3),(x+4,y+1),(x+9,y+5),(x+15,y+6),(x+15,y+8),(x,y+8)],mid)
        a.line([(x+2,y+4),(x+5,y+4),(x+9,y+7)],light)
        a.line([(x+10,y+7),(x+13,y+7)],2)
        a.box(x,y,16,9)
    elif kind=='open':
        a.shape([(x,y+8),(x+1,y+3),(x+3,y+2),(x+4,y+6),(x+5,y),(x+7,y),(x+8,y+5),(x+10,y+2),(x+12,y+3),(x+11,y+9),(x+8,y+13),(x+3,y+14)],mid)
        a.patch([(x+3,y+6),(x+6,y+4),(x+7,y+8),(x+10,y+6),(x+9,y+10),(x+6,y+12),(x+3,y+11)],light)
        a.line([(x+2,y+9),(x+5,y+10)],2)
        a.box(x,y,13,15)
    else:
        a.shape([(x+2,y),(x+7,y),(x+10,y+3),(x+10,y+8),(x+7,y+11),(x+2,y+10),(x,y+7),(x,y+3)],mid)
        a.patch([(x+3,y+1),(x+7,y+2),(x+9,y+4),(x+8,y+5),(x+2,y+4)],light)
        a.line([(x+2,y+7),(x+5,y+8),(x+8,y+6)],2 if near else 1)
        a.line([(x+5,y+5),(x+7,y+6)],mid)
        a.box(x,y,11,12)

def arm(who,side,pose='guard'):
    near=side=='near_arm';a=Ink()
    table=(KENJI_NEAR if near else KENJI_FAR) if who=='kenji' else (JACK_NEAR if near else JACK_FAR) if who=='jack' else (AMARA_NEAR if near else AMARA_FAR)
    fallback=(KENJI_NEAR if near else KENJI_FAR)
    data=table.get(pose)
    if data is None:
        if pose not in ('down','fall','floor'):raise ValueError(who+'/'+side+'/'+pose)
        # Lying/falling poses have separate contours; material marks still
        # differ. No standing limb is rotated into a floor drawing.
        data=fallback[pose]
    outer,plane,origin=data[:3]
    a.shape(outer,4 if near else 3)
    silhouette=np.asarray(a.image).copy()>0
    a.patch(plane,5 if near else 4)
    a.line(plane[:3],6 if near else 5)
    pixels=np.asarray(a.image).copy();pixels[~silhouette]=0;a.image=Image.fromarray(pixels,'P');a.d=ImageDraw.Draw(a.image)
    if who=='kenji':
        sleeve=data[3]
        if sleeve=='guard':
            shape=[(59,52),(67,52),(73,60),(77,70),(74,78),(66,80),(59,73),(55,62)] if near else [(93,51),(100,52),(106,60),(108,68),(102,73),(96,67)]
